import { readFileSync } from 'node:fs';
import { describe, it, expect } from 'vitest';
import { parse } from '../parser/index.js';
import { simulate } from '../simulate.js';
import { BSIM3v3 } from './bsim3v3.js';
import { evaluateDC } from './bsim3v3-dc.js';
import { chargeParams, createTerminalCharges, evaluateTerminalCharges } from './bsim3v3-charge.js';

// Issue #594: ngspice-47 bsim3v32 reference values for LEVEL=8/49
// VERSION=3.2.x cards on identical decks, generated by
// benchmarks/bsim3v32-594/reference.ts (`ngspice -b`, numdgt=15): the b3v32ld.c
// operating-point outputs and terminal currents (DC), the charge outputs and
// AC terminal capacitance matrices (charge), and an inverter chain of the
// corpus-f TSMC VERSION = 3.2.2 cards (transient).
interface DcPoint {
  vgs: number; vds: number; vbs: number;
  id: number; gm: number; gds: number; gmbs: number; vth: number; ivd: number;
}
interface DcCase {
  name: string;
  type: 1 | -1;
  operatingPoints: { deck: string; points: DcPoint[] };
  sweep: { deck: string; points: { vd: number; ivd: number }[] };
}
type Quantity = 'cgg' | 'cgd' | 'cgs' | 'cbg' | 'cbd' | 'cbs' | 'cdg' | 'cdd' | 'cds'
  | 'qg' | 'qb' | 'qd' | 'capbd' | 'capbs';
type Source = 'vg' | 'vd' | 'vb';
interface Bias { vgs: number; vds: number; vbs: number }
interface ChargeCase {
  name: string;
  type: 1 | -1;
  charges: { deck: string; points: (Bias & Record<Quantity, number>)[] };
  ac: { deck: string; frequency: number; points: (Bias & { c: Record<Source, Record<Source, number>> })[] };
}
type TranSignal = 'v(n1)' | 'v(n2)' | 'v(out)' | 'q(vdd)';
const reference = JSON.parse(readFileSync(
  new URL('../../../../benchmarks/bsim3v32-594/ngspice-47-bsim3v32.json', import.meta.url), 'utf8',
)) as {
  engine: string;
  dc: DcCase[];
  charge: ChargeCase[];
  transient: {
    deck: string; window: number; peak: Record<TranSignal, number>;
    samples: ({ time: number } & Record<TranSignal, number>)[];
  };
};

// The #589/#626 acceptance: within 1% of ngspice-47; values below the floor
// (A, S, F or C) are compared absolutely.
const RELATIVE = 0.01;
const DC_FLOOR = 1e-12;
const CHARGE_FLOOR = 1e-21;

function relativeError(actual: number, expected: number, floor: number): number {
  return Math.abs(actual - expected) / Math.max(Math.abs(expected), floor);
}

function deviceOf(deck: string): BSIM3v3 {
  const device = parse(deck).compile().devices.find((d): d is BSIM3v3 => d instanceof BSIM3v3);
  if (!device) throw new Error('no BSIM3 device in deck');
  return device;
}

function interpolate(time: readonly number[], values: readonly number[], t: number): number {
  const j = time.findIndex(x => x >= t);
  if (j <= 0) return values[Math.max(j, 0)];
  return values[j - 1] + (values[j] - values[j - 1]) * (t - time[j - 1]) / (time[j] - time[j - 1]);
}

function integrate(time: readonly number[], values: readonly number[], lo: number, hi: number): number {
  const points: [number, number][] = [[lo, interpolate(time, values, lo)]];
  for (let k = 0; k < time.length; k++) if (time[k] > lo && time[k] < hi) points.push([time[k], values[k]]);
  points.push([hi, interpolate(time, values, hi)]);
  let charge = 0;
  for (let k = 1; k < points.length; k++) charge += 0.5 * (points[k][1] + points[k - 1][1]) * (points[k][0] - points[k - 1][0]);
  return charge;
}

class Worst {
  error = 0;
  label = '';
  add(error: number, label: () => string): void {
    if (!(error <= this.error)) { this.error = error; this.label = label(); }
  }
}

describe('BSIM3v32 (VERSION=3.2.x) matches ngspice-47 bsim3v32 (#594)', () => {
  it('uses the ngspice-47 reference', () => {
    expect(reference.engine).toBe('ngspice-47');
    expect(reference.dc.length).toBeGreaterThanOrEqual(10);
    expect(reference.charge.length).toBeGreaterThanOrEqual(22);
  });

  for (const c of reference.dc) {
    it(`${c.name}: Id, gm, gds, gmbs and Vth at ${c.operatingPoints.points.length} biases`, () => {
      const device = deviceOf(c.operatingPoints.deck);
      const worst = new Worst();
      for (const p of c.operatingPoints.points) {
        // b3v32ld.c BSIM3v32mode = -1 evaluates (Vgd, -Vds, Vbd); @m1[...] report that orientation.
        const reverse = p.vds < 0;
        const dc = evaluateDC(
          device.model, device.size,
          reverse ? p.vgs - p.vds : p.vgs, Math.abs(p.vds), reverse ? p.vbs - p.vds : p.vbs,
        );
        const m = device.size.m;
        const checks: [string, number, number, number][] = [
          ['id', m * dc.Ids, p.id, DC_FLOOR],
          ['gm', m * dc.gm, p.gm, DC_FLOOR],
          ['gds', m * dc.gds, p.gds, DC_FLOOR],
          ['gmbs', m * dc.gmbs, p.gmbs, DC_FLOOR],
          ['vth', dc.von, p.vth, 1],
        ];
        for (const [label, actual, expected, floor] of checks) {
          worst.add(relativeError(actual, expected, floor),
            () => `${label} at Vgs=${p.vgs} Vds=${p.vds} Vbs=${p.vbs}: ${actual} vs ${expected}`);
        }
      }
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });

    it(`${c.name}: terminal i(VD) at every operating point`, async () => {
      const worst = new Worst();
      for (const p of c.operatingPoints.points) {
        const deck = c.operatingPoints.deck
          .replace(/^VD d 0 DC .*$/m, `VD d 0 DC ${c.type * p.vds}`)
          .replace(/^VG g 0 DC .*$/m, `VG g 0 DC ${c.type * p.vgs}`)
          .replace(/^VB b 0 DC .*$/m, `VB b 0 DC ${c.type * p.vbs}`)
          .replace(/^\.end$/m, '.op\n.end');
        const current = (await simulate(deck)).dc!.current('VD');
        worst.add(relativeError(current, p.ivd, DC_FLOOR),
          () => `i(VD) at Vgs=${p.vgs} Vds=${p.vds} Vbs=${p.vbs}: ${current} vs ${p.ivd}`);
      }
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });

    it(`${c.name}: terminal i(VD) matches the ngspice Id-Vds sweep`, async () => {
      const current = (await simulate(c.sweep.deck)).dcSweep!.current('VD');
      expect(current.length).toBe(c.sweep.points.length);
      const worst = new Worst();
      c.sweep.points.forEach((p, i) => {
        worst.add(relativeError(current[i], p.ivd, DC_FLOOR), () => `i(VD) at VD=${p.vd}: ${current[i]} vs ${p.ivd}`);
      });
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });
  }

  for (const c of reference.charge) {
    it(`${c.name}: intrinsic capacitances, state charges and junction capacitances`, () => {
      const device = deviceOf(c.charges.deck);
      const params = chargeParams(device.model, device.size);
      const out = createTerminalCharges();
      const worst = new Worst();
      for (const p of c.charges.points) {
        const tc = evaluateTerminalCharges(device.model, device.size, params, p.vgs, p.vds, p.vbs, out);
        const ic = tc.intrinsic;
        // b3v32ask.c reports every one of these multiplied by M.
        const m = device.size.m;
        const actual: Record<Quantity, number> = {
          cgg: m * ic.cggb, cgd: m * ic.cgdb, cgs: m * ic.cgsb, cbg: m * ic.cbgb, cbd: m * ic.cbdb,
          cbs: m * ic.cbsb, cdg: m * ic.cdgb, cdd: m * ic.cddb, cds: m * ic.cdsb,
          qg: m * tc.qg, qb: m * tc.qb, qd: m * tc.qd, capbd: m * tc.capbd, capbs: m * tc.capbs,
        };
        for (const q of Object.keys(actual) as Quantity[]) {
          worst.add(relativeError(actual[q], p[q], CHARGE_FLOOR),
            () => `${q} at Vgs=${p.vgs} Vds=${p.vds} Vbs=${p.vbs}: ${actual[q]} vs ${p[q]}`);
        }
      }
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });

    it(`${c.name}: AC terminal capacitance matrix`, async () => {
      const omega = 2 * Math.PI * c.ac.frequency;
      const worst = new Worst();
      for (const p of c.ac.points) {
        for (const excited of ['vg', 'vd', 'vb'] as const) {
          const deck = c.ac.deck
            .replace(/^VD d 0 DC 0 AC 0$/m, `VD d 0 DC ${c.type * p.vds} AC ${excited === 'vd' ? 1 : 0}`)
            .replace(/^VG g 0 DC 0 AC 0$/m, `VG g 0 DC ${c.type * p.vgs} AC ${excited === 'vg' ? 1 : 0}`)
            .replace(/^VB b 0 DC 0 AC 0$/m, `VB b 0 DC ${c.type * p.vbs} AC ${excited === 'vb' ? 1 : 0}`)
            .replace(/^\.end$/m, `.ac lin 1 ${c.ac.frequency} ${c.ac.frequency}\n.end`);
          const ac = (await simulate(deck)).ac!;
          for (const measured of ['vg', 'vd', 'vb'] as const) {
            const { magnitude, phase } = ac.current(measured.toUpperCase())[0];
            const capacitance = magnitude * Math.sin(phase * Math.PI / 180) / omega;
            const expected = p.c[excited][measured];
            worst.add(relativeError(capacitance, expected, CHARGE_FLOOR),
              () => `d i(${measured})/d ${excited} at Vgs=${p.vgs} Vds=${p.vds} Vbs=${p.vbs}: ${capacitance} vs ${expected}`);
          }
        }
      }
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });
  }

  it('TSMC 3.2.2 inverter chain transient: node voltages and supply charge within 1% of ngspice-47', async () => {
    const tran = reference.transient;
    const result = (await simulate(tran.deck)).transient!;
    const time = result.time;
    const supply = result.current('VDD');
    const half = tran.window / 2;
    const worst = new Worst();
    for (const sample of tran.samples) {
      const actual: Record<TranSignal, number> = {
        'v(n1)': interpolate(time, result.voltage('n1'), sample.time),
        'v(n2)': interpolate(time, result.voltage('n2'), sample.time),
        'v(out)': interpolate(time, result.voltage('out'), sample.time),
        'q(vdd)': integrate(time, supply, sample.time - half, sample.time + half),
      };
      for (const signal of Object.keys(actual) as TranSignal[]) {
        worst.add(Math.abs(actual[signal] - sample[signal]) / tran.peak[signal],
          () => `${signal} at ${sample.time}: ${actual[signal]} vs ${sample[signal]}`);
      }
    }
    expect(worst.error, worst.label).toBeLessThan(RELATIVE);
  });
});
